//! Gender, which decides the cells some declensions refer to others, and which
//! words have which. The rule with the longest ending the word has decides;
//! the words no rule gets right are listed.

use super::cell::*;
use crate::Gender::{self, *};
use flexion::{Choice, Referral};
use std::borrow::Cow;

/// The cells whose form, in the declensions that say `referred`, is another
/// cell's: per gender, in order (Masculine, Feminine, Neuter), the cell.
pub(super) static REFERRALS: [Referral<'static>; 1] = [Referral {
    cell: DAT_SG,
    to: Cow::Borrowed(&[NOM_SG, GEN_SG, NOM_SG]),
}];

